import numpy as np
def f(g):
    g=np.array(g); H,W=g.shape; out=g.copy()
    cnt=Counter(map(int,g.flatten())); bg=cnt.most_common(1)[0][0]
    for i in range(H):
        for j in range(W):
            v=int(g[i,j])
            if v==bg: continue
            nb=[]
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                x,y=i+dx,j+dy
                if 0<=x<H and 0<=y<W: nb.append(int(g[x,y]))
            # majority among neighbors of the other colors
            c={}
            for b in nb: c[b]=c.get(b,0)+1
            best={}
            for k,vw in c.items():
                if vw==max(c.values()) and k!=bg: best[k]=vw
            # pick most common noise color among neighbors
            mc=c.most_common(1)[0][0] if c else bg
            out[i,j]=mc
    return out.tolist()
