from collections import Counter
def f(g):
    g=np.array(g); H,W=g.shape; out=g.copy()
    bg=int(Counter(map(int,g.flatten())).most_common(1)[0][0])
    def comp_size(col):
        seen=np.zeros((H,W),bool); s=0
        for i in range(H):
            for j in range(W):
                if g[i,j]==col and not seen[i,j]:
                    st=[(i,j)]; c=0
                    while st:
                        x,y=st.pop()
                        if 0<=x<H and 0<=y<W and g[x,y]==col and not seen[x,y]:
                            seen[x,y]=True; c+=1; st.append((x+1,y)); st.append((x-1,y)); st.append((x,y+1)); st.append((x,y-1))
                    s+=c
        return s
    for i in range(H):
        for j in range(W):
            v=int(g[i,j]); if v==bg: continue
            nb=[]
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                x,y=i+dx,j+dy
                if 0<=x<H and 0<=y<W: nb.append(int(g[x,y]))
            if not nb:
                out[i,j]=bg
                continue
            c=Counter(nb)
            # tie-break: largest connected component of the color
            best=None
            for col,n in c.most_common():
                sz=comp_size(col)
                if best is None or sz>best[0]: best=(sz,col)
            out[i,j]=best[1]
    return out.tolist()
