def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
gi=np.array(G['Demo pair 1 input']); go=np.array(G['Demo pair 1 output'])

def f(g):
    g=np.array(g); H,W=g.shape
    bg=int(Counter(map(int,g.flatten())).most_common(1)[0][0])
    seen=set(); blocks=[]
    for i in range(H):
        for j in range(W):
            if (i,j) in seen or int(g[i,j])==bg: continue
            st=[(i,j)]; seen.add((i,j)); comp=[]
            while st:
                x,y=st.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<W and int(g[xx,yy])==int(g[i,j]) and (xx,yy) not in seen:
                        seen.add((xx,yy)); st.append((xx,yy))
            if len(comp)>1: blocks.append((int(g[i,j]),comp))
    out=g.copy()
    for i in range(H):
        for j in range(W):
            v=int(g[i,j])
            if v==bg: continue
            kept=False
            for color,comp in blocks:
                if (i,j) in comp: kept=True; break
            if not kept: out[i,j]=bg
    return out.tolist()
print('demo ok:', f(gi)==go.tolist())
ti=np.array(G['Test input'])
out=f(ti)
diff=[(i,j,int(ti[i][j]),out[i][j]) for i in range(len(ti)) for j in range(len(ti[0])) if out[i][j]!=ti[i][j]]
print(json.dumps(out))
print('ndiff',len(diff)); print(diff)

