def f(g):
    g=np.array(g); H,W=g.shape; out=g.copy()
    bg=int(Counter(map(int,g.flatten())).most_common(1)[0][0])
    seen=set(); blocks=[]
    for i in range(H):
        for j in range(W):
            if (i,j) in seen or int(g[i,j])==bg: continue
            st=[(i,j)]; seen.add((i,j)); comp=[]
            while st:
                x,y=st.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<W and int(g[xx,yy])==int(g[i,j]) and (xx,yy) not in seen:
                        seen.add((xx,yy)); st.append((xx,yy))
            if len(comp)>1: blocks.append(comp)
    def best(nb):
        c=Counter(nb)
        if not c: return bg
        items=list(c.items())
        # prefer largest count; ties -> smaller color, but never pick bg unless forced
        nonbg=[k for k in c if k!=bg]
        if any(k!=bg for k in c):
            cand=sorted(nonbg,key=lambda k:(-c[k],k))
        else:
            cand=sorted([k for k in c],key=lambda k:(-c[k],k))
