        return min(k,bg,max=-1) if False else (max(-c.get(bg,0),sum(c.values())) and 
                                           k if k!=bg and -k>=0 else bg)
    # simpler: if exists non-bg candidate -> choose best non-bg (count desc, color asc); else bg
    for i in range(H):
        for j in range(W):
            v=int(g[i,j]); keep=True
