def components(g,v):
    H,W=g.shape; seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if (i,j) in seen or int(g[i,j])!=v: continue
            st=[(i,j)]; comp={(i,j)}; seen.add((i,j))
            while st:
                x,y=st.pop()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<W and (xx,yy) not in seen and int(g[xx,yy])==v:
                        seen.add((xx,yy)); comp.add((xx,yy)); st.append((xx,yy))
            out.append(comp)
    return out
