# Hypothesis H: every cell (including bg!) gets recolored by majority of ortho neighbors,
# excluding the background color from candidates; bg itself excluded; ties: prefer non-bg; 
# if exactly one candidate... try several tie variants.
def score(gi,go,tie_key):
    gi=np.array(gi); go=np.array(go); H,W=gi.shape; ok=True; mism=[]
    bgc=int(Counter(map(int,gi.flatten())).most_common(1)[0][0])
    for i in range(H):
        for j in range(W):
            nb=[]
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
