                if 0<=x<H and 0<=y<W: nb.append(int(gi[x,y]))
            c=Counter(nb)
            cand=[k for k in c if k!=bgc]
            if not cand:
                pred=bgc
            else:
                pred=max(cand,key=lambda k:(c[k],tie_key(k)))
            if pred!=go[i,j]:
                ok=False; mism.append((i,j,int(pred),int(go[i,j])))
    return ok,mism
