def solve(g, conn=4, diag=False):
    g=np.array(g); H,W=g.shape; out=g.copy()
    bgc=int(Counter(map(int,g.flatten())).most_common(1)[0][0])
    seen=set(); blocks=[]
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    if diag: dirs+=((-1,-1),(-1,1),(1,-1),(1,1))
    for i in range(H):
        for j in range(W):
            if (i,j) in seen or int(g[i,j])==bgc: continue
            v=int(g[i,j]); st=[(i,j)]; comp={(i,j)}; seen.add((i,j))
            while st:
                x,y=st.pop()
                for dx,dy in dirs:
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<W and (xx,yy) not in seen and int(g[xx,yy])==v:
                        seen.add((xx,yy)); comp.add((xx,yy)); st.append((xx,yy))
            if len(comp)>1: blocks.append((v,comp))
    def vote(i,j,cand_key=bgc):
        nb=[]
        for dx,dy in dirs:
            x,y=i+dx,j+dy
            if 0<=x<H and 0<=y<W: nb.append(int(g[x,y]))
        c=Counter(nb)
        cand=[k for k in c if k!=bgc and k!=cand_key]
        if cand:
            def mk(k): return (c[k], -k) if k!=cand_key else (-1e9,-1e9)
            return max(cand,key=mk)
        return None
    for (v,comp) in blocks:
        comps = [dict.fromkeys(comp)]
        for ii in range(H):
            for jj in range(W):
                if (ii,jj) in set().union(*comps) or int(g[ii,jj])==bgc: continue
