def components(g, bgc):
    g=np.array(g); H,W=g.shape; seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if (i,j) in seen or g[i,j]==bgc: continue
            st=[(i,j)]; comp={(i,j)}; seen.add((i,j))
            while st:
                x,y=st.pop()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<W and (xx,yy) not in seen and g[xx,yy]==g[x,y]:
